[PlanningStep(reason='To improve code organization and clarity, separate the management of virtual base tables (VBT) and virtual function tables (VFT) into distinct root nodes.', final_code='private ParentageNode vbtRoot; // New root for VBT
private ParentageNode vftRoot; // New root for VFT

// In the constructor, initialize vbtRoot and vftRoot
this.vbtRoot = new ParentageNode(null);
this.vftRoot = new ParentageNode(null);', execution_details="Extract the management of virtual base tables (VBT) and virtual function tables (VFT) into a new class named 'VxtRootManager'. Move the fields 'vbtRoot' and 'vftRoot' along with their initialization logic from 'MsftVxtManager' to 'VxtRootManager'. Update 'MsftVxtManager' to use an instance of 'VxtRootManager' for managing VBT and VFT. Ensure that all methods in 'MsftVxtManager' that interact with VBT and VFT are updated to call the corresponding methods on the new 'VxtRootManager' instance.", refactoring_type=<SupportedRefactorings.EXTRACT_CLASS: 'extract_class'>, file_path='Ghidra/Features/PDB/src/main/java/ghidra/app/util/pdb/classtype/MsftVxtManager.java'), PlanningStep(reason='To enhance readability and maintainability, update methods to use the new distinct root nodes for VBT and VFT, ensuring that the correct root node is utilized in each relevant method.', final_code='private ParentageNode findNode(ClassID owner, List<ClassID> parentage) {
    if (!(owner instanceof ProgramClassID ownerGId)) {
        return null;
    }
    SymbolPath ownerSp = ownerGId.getSymbolPath();
    ParentageNode ownerNode = vbtRoot.getBranch(ownerSp.toString()); // Use vbtRoot for VBT
    if (ownerNode == null) {
        ownerNode = vftRoot.getBranch(ownerSp.toString()); // Use vftRoot for VFT
    }
    if (ownerNode == null) {
        return null;
    }
    ParentageNode resultNode = null;
    ParentageNode node = ownerNode;
    for (ClassID id : parentage) {
        if (!(id instanceof ProgramClassID gId)) {
            return null;
        }
        SymbolPath sp = gId.getSymbolPath();
        ParentageNode next = node.getBranch(sp.toString());
        if (next != null) {
            node = next;
            resultNode = node;
        }
    }
    return resultNode != null ? resultNode : ownerNode;
}

private ParentageNode getOrAddParentageNode(CategoryPath categoryPath, ParentageNode root, DemanglerResults demanglerResults) {
    ParentageNode node = root;
    OwnerAndParentage ownerAndParentage = demanglerResults.ownerAndParentage();
    ClassID owner = ownerAndParentage.owner();
    List<ClassID> parentage = ownerAndParentage.parentage();
    if (!(owner instanceof ProgramClassID)) {
        Msg.error(this, "ClassID error for " + ownerAndParentage);
        return null;
    }
    ProgramClassID gId = (ProgramClassID) owner;
    node = node.getOrAddBranch(gId.getSymbolPath().toString());
    for (ClassID id : parentage) {
        if (!(id instanceof ProgramClassID)) {
            Msg.error(this, "ClassID error for " + ownerAndParentage);
            return null;
        }
        gId = (ProgramClassID) id;
        node = node.getOrAddBranch(gId.getSymbolPath().toString());
    }
    return node;
}', execution_details='Update the findNode method to check both vbtRoot and vftRoot for the owner node, ensuring that the correct root is used based on the context. Ensure that the logic for traversing the parentage remains intact. In getOrAddParentageNode, ensure that the logic for adding branches is consistent with the new structure.', refactoring_type=<SupportedRefactorings.MOVE: 'move'>, file_path='Ghidra/Features/PDB/src/main/java/ghidra/app/util/pdb/classtype/MsftVxtManager.java'), PlanningStep(reason='To clarify the lookup mechanisms, enhance documentation for methods related to VBT and VFT, and ensure that the method signatures are consistent with the intended functionality.', final_code='/**
